dirs={'en':'values','id':'values-in','he':'values-iw','ko':'values-ko-rKR','zh_CN':'values-zh-rCN'}
def xml(s):return html.escape(s,quote=False).replace("'","\\'").replace('"','\\"')
for lang,notes in text.items():
    folder=repo/'app/src/main/res'/dirs.get(lang,'values-'+lang)
    assert folder.exists(),folder
    lines=['<?xml version="1.0" encoding="utf-8"?>','<resources>']
    for r in rows:
        name=r.get('localizedNames',{}).get(lang,r['name'])
        nucleus={'en':'nucleus','it':'nucleo','de':'Kern','fr':'noyau','es':'núcleo','pt':'núcleo','nl':'kern',
            'pl':'jądro','ru':'ядро','tr':'çekirdek','el':'πυρήνας','ar':'نواة','fa':'هسته','he':'גרעין',
            'hi':'नाभिक','id':'inti','sw':'kiini','ja':'核','ko':'핵','zh_CN':'星系核'}
        if name.endswith(' nucleus'):name=name[:-8]+' · '+nucleus[lang]
        lines.append('    <string name="catalogue_'+r['key']+'">'+xml(name)+'</string>')
    for key,note in zip(keys,notes):lines.append('    <string name="catalogue_'+key+'">'+xml(note)+'</string>')
    lines.append('</resources>')
    content='\n'.join(lines)+'\n'
    if CHECK:assert (folder/'catalogue_999.xml').read_text(encoding='utf-8')==content,lang
    else:(folder/'catalogue_999.xml').write_text(content,encoding='utf-8')
print('Generated matching resources for',len(text),'languages; international identifiers are retained verbatim.')
